const TransferTicketsScreen = ({ order, onCancel, onComplete }) => {
  const [selectedTickets, setSelectedTickets] = useState([]);
  const [step, setStep] = useState('select');
  const [recipient, setRecipient] = useState({ firstName: '', lastName: '', email: '' });
  const toggleTicket = (seat) => setSelectedTickets((current) => current.includes(seat) ? current.filter((item) => item !== seat) : [...current, seat]);
  const toggleAll = () => setSelectedTickets((current) => current.length === order.seats.length ? [] : [...order.seats]);
  const recipientReady = recipient.firstName.trim() && recipient.lastName.trim() && /\S+@\S+\.\S+/.test(recipient.email);
  const isSelectionStep = step === 'select';
  return <SafeAreaView style={styles.transferScreen} edges={['top']}><View style={styles.transferHeader}><TouchableOpacity onPress={isSelectionStep ? onCancel : () => setStep('select')} style={styles.transferClose}><Text style={styles.transferCloseText}>{isSelectionStep ? '×' : '‹'}</Text></TouchableOpacity><Text style={styles.transferHeaderTitle}>Transfer Tickets</Text><View style={styles.transferHeaderSpacer} /></View><ScrollView contentContainerStyle={styles.transferContent}><Image source={eventImageSource(order.event.image)} style={styles.transferEventImage} /><View style={styles.transferEventInfo}><Text style={styles.transferEventName}>{order.event.name}</Text><Text style={styles.transferEventMeta}>{day(order.event)} · {order.event.time}</Text><Text style={styles.transferEventMeta}>{order.event.venue}</Text></View>{isSelectionStep ? <><Text style={styles.transferTitle}>Transfer Tickets</Text><Text style={styles.transferCopy}>Select the tickets for this event that you would like to transfer. Once selected, tap Continue.</Text><View style={styles.transferListHeader}><Text style={styles.transferListTitle}>TICKETS</Text><Text style={styles.transferCount}>Selected ({selectedTickets.length} of {order.seats.length})</Text></View><TouchableOpacity onPress={toggleAll} style={styles.selectAllRow}><View style={[styles.transferCheckbox, selectedTickets.length === order.seats.length && styles.transferCheckboxSelected]}>{selectedTickets.length === order.seats.length && <Text style={styles.transferCheck}>✓</Text>}</View><Text style={styles.selectAllText}>Select all tickets</Text></TouchableOpacity>{order.seats.map((seat, index) => <TouchableOpacity key={`${seat}-${index}`} onPress={() => toggleTicket(seat)} style={styles.transferTicketRow}><View style={[styles.transferCheckbox, selectedTickets.includes(seat) && styles.transferCheckboxSelected]}>{selectedTickets.includes(seat) && <Text style={styles.transferCheck}>✓</Text>}</View><View><Text style={styles.transferSeatText}>{seat.replaceAll('-', ' · ')}</Text><Text style={styles.transferSeatSub}>{isBTSEvent(order.event) ? btsTicketType(seat.split('-')[0]) : 'Standard ticket'} · Ticket {index + 1} of {order.quantity}</Text></View></TouchableOpacity>)}</> : <View style={styles.recipientForm}><Text style={styles.transferTitle}>Who are you sending tickets to?</Text><Text style={styles.transferCopy}>They’ll receive an email with instructions to accept {selectedTickets.length} ticket{selectedTickets.length === 1 ? '' : 's'}.</Text><Text style={styles.recipientLabel}>FIRST NAME</Text><TextInput value={recipient.firstName} onChangeText={(firstName) => setRecipient((current) => ({ ...current, firstName }))} style={styles.recipientInput} placeholder="First name" autoCapitalize="words" /><Text style={styles.recipientLabel}>LAST NAME</Text><TextInput value={recipient.lastName} onChangeText={(lastName) => setRecipient((current) => ({ ...current, lastName }))} style={styles.recipientInput} placeholder="Last name" autoCapitalize="words" /><Text style={styles.recipientLabel}>EMAIL ADDRESS</Text><TextInput value={recipient.email} onChangeText={(email) => setRecipient((current) => ({ ...current, email }))} style={styles.recipientInput} placeholder="name@example.com" keyboardType="email-address" autoCapitalize="none" /></View>}</ScrollView><View style={styles.transferFooter}><TouchableOpacity onPress={isSelectionStep ? onCancel : () => setStep('select')} style={styles.cancelTransfer}><Text style={styles.cancelTransferText}>{isSelectionStep ? 'Cancel' : 'Back'}</Text></TouchableOpacity><TouchableOpacity disabled={isSelectionStep ? !selectedTickets.length : !recipientReady} onPress={() => isSelectionStep ? setStep('recipient') : onComplete(selectedTickets)} style={[styles.continueTransfer, (isSelectionStep ? !selectedTickets.length : !recipientReady) && styles.continueTransferDisabled]}><Text style={styles.continueTransferText}>{isSelectionStep ? 'Continue' : 'Transfer tickets'}</Text></TouchableOpacity></View></SafeAreaView>;
};

