  useEffect(() => { if (!isTicketmasterConfigured()) return; const timer = setTimeout(() => loadLiveEvents(0), query ? 450 : 0); return () => clearTimeout(timer); }, [category, query, location.code, loadLiveEvents]);
  const displayedEvents = liveEvents.length ? liveEvents : filtered;
  const formatMoney = (amount) => money(amount, settings.currency);
  const subtotal = selected ? selected.price * quantity : 0; const fees = Math.ceil(subtotal * feeRate / 100); const total = subtotal + fees;
