  if (screen === 'seats') return top(<ScrollView contentContainerStyle={styles.page}><Text style={styles.step}>STEP 2 OF 4</Text><Text style={styles.pageTitle}>Pick your seats</Text><Text style={styles.pageLead}>Choose a section, row, then {quantity} seat{quantity > 1 ? 's' : ''}.</Text><Text style={styles.selectionHeading}>1. SECTION</Text>{isBTSEvent(selected) && <Text style={styles.btsSectionHelper}>BTS ticket type is assigned automatically: Sections 1–50 VIP Soundcheck, 51–100 VIP, and 101+ ARMY Membership Presale.</Text>}<View style={styles.choiceGrid}>{(isBTSEvent(selected) ? btsSeatSections : seatSections).map((section) => <TouchableOpacity key={section} onPress={() => { setSelectedSection(section); setSelectedRow(section === 'GA' ? 'GA' : null); setChosenSeats([]); }} style={[styles.choiceChip, selectedSection === section && styles.choiceChipSelected]}><Text style={[styles.choiceChipText, selectedSection === section && styles.choiceChipTextSelected]}>{section === 'GA' ? 'General Admission' : `Section ${section}`}</Text></TouchableOpacity>)}</View>{isBTSEvent(selected) && selectedSection && <View style={styles.btsTicketType}><Text style={styles.btsTicketTypeLabel}>YOUR BTS TICKET TYPE</Text><Text style={styles.btsTicketTypeValue}>{btsTicketType(selectedSection)}</Text></View>}{selectedSection && selectedSection !== 'GA' && <><Text style={styles.selectionHeading}>2. ROW</Text><View style={styles.choiceGrid}>{seatRows.map((row) => <TouchableOpacity key={row} onPress={() => { setSelectedRow(row); setChosenSeats([]); }} style={[styles.rowChip, selectedRow === row && styles.choiceChipSelected]}><Text style={[styles.choiceChipText, selectedRow === row && styles.choiceChipTextSelected]}>{row}</Text></TouchableOpacity>)}</View></>}{selectedSection && selectedRow && <><Text style={styles.selectionHeading}>{selectedSection === 'GA' ? '2. ADMISSION TICKETS' : '3. SEAT NUMBER'}</Text><View style={styles.stage}><Text style={styles.stageText}>{selectedSection === 'GA' ? 'GENERAL ADMISSION' : 'STAGE'}</Text></View><View style={styles.seatGrid}>{seatNumbers.map((number) => { const seatKey = selectedSection === 'GA' ? `GA-GA-${number}` : `${selectedSection}-${selectedRow}-${number}`; return <TouchableOpacity key={seatKey} onPress={() => toggleSeat(seatKey)} style={[styles.seat, chosenSeats.includes(seatKey) && styles.seatSelected, chosenSeats.length >= quantity && !chosenSeats.includes(seatKey) && styles.seatMuted]}><Text style={[styles.seatText, chosenSeats.includes(seatKey) && styles.seatTextSelected]}>{number}</Text></TouchableOpacity>; })}</View></>}<TouchableOpacity onPress={chooseBest} style={styles.best}><Text style={styles.bestTitle}>Best available</Text><Text style={styles.bestCopy}>Select {selectedSection ? `in ${selectedSection}${selectedRow ? `, Row ${selectedRow}` : ''}` : 'the best location'} for me</Text></TouchableOpacity><Text style={styles.selection}>{chosenSeats.length} of {quantity} selected</Text><TouchableOpacity disabled={chosenSeats.length !== quantity} onPress={() => setScreen('review')} style={[styles.primary, chosenSeats.length !== quantity && styles.disabled]}><Text style={styles.primaryText}>Reserve tickets</Text></TouchableOpacity></ScrollView>);
